INSERT INTO public.bible_verses (topic, reference, text_es) VALUES
-- Money (Proverbios, Deuteronomio, etc.)
('Money', 'Proverbios 23:4-5', 'No te afanes por hacerte rico; sé prudente, y desiste. ¿Has de poner tus ojos en las riquezas, siendo ningunas? Porque se harán alas como alas de águila, y volarán al cielo.'),
('Money', 'Deuteronomio 8:18', 'Sino acuérdate de Jehová tu Dios, porque él te da el poder para hacer las riquezas, a fin de confirmar su pacto que juró a tus padres, como en este día.'),
('Money', '1 Timoteo 6:17-19', 'A los ricos de este siglo manda que no sean altivos, ni pongan la esperanza en las riquezas, las cuales son inciertas, sino en el Dios vivo, que nos da todas las cosas en abundancia para que las disfrutemos. Que hagan bien, que sean ricos en buenas obras, dadivosos, generosos; atesorando para sí buen fundamento para lo por venir, que echen mano de la vida eterna.'),
('Money', 'Salmos 12:5', 'Por la opresión de los pobres, por el gemido de los menesterosos, ahora me levantaré, dice Jehová; pondré en salvo al que por ello suspira.'),
('Money', 'Salmos 37:16', 'Mejor es lo poco del justo, que las riquezas de muchos pecadores.'),
('Money', 'Eclesiastés 4:6', 'Mejor es un puño lleno con descanso, que ambos puños llenos con trabajo y aflicción de espíritu.'),
('Money', 'Proverbios 17:5', 'El que escarnece al pobre afrenta a su Hacedor; y el que se alegra de la calamidad no quedará sin castigo.'),
('Money', '1 Crónicas 29:12', 'Las riquezas y la gloria proceden de ti, y tú dominas sobre todo; en tu mano está la fuerza y el poder, y en tu mano el hacer grande y el dar poder a todos.'),
('Money', 'Ezequiel 7:19', 'Arrojarán su plata en las calles, y su oro será desechado; ni su plata ni su oro podrá librarlos en el día del furor de Jehová; no saciarán su alma, ni llenarán sus entrañas, porque su maldad ha sido tropezadero para ellos.'),
('Money', 'Eclesiastés 5:12-14', 'Dulce es el sueño del trabajador, coma mucho o coma poco; pero al rico no le deja dormir la abundancia. Hay una grave enfermedad que he visto bajo el sol: las riquezas guardadas por sus dueños para su mal; las cuales se pierden en malos negocios, y a los hijos que engendraron, nada les queda en la mano.'),
('Money', 'Santiago 2:5', 'Hermanos míos amados, oíd: ¿No ha elegido Dios a los pobres de este mundo, para que sean ricos en fe y herederos del reino que ha prometido a los que le aman?'),
('Money', 'Proverbios 15:16', 'Mejor es lo poco con el temor de Jehová, que el gran tesoro donde hay turbación.'),

-- Wealth, Possessions, Riches
('Wealth, Posessions, Riches', 'Proverbios 13:4', 'El alma del perezoso desea, y nada alcanza; pero el alma de los diligentes será prosperada.'),

-- Help in Troubles
('Help in Troubles', 'Salmos 37:39', 'Pero la salvación de los justos es de Jehová, y él es su fortaleza en el tiempo de la angustia.'),
('Help in Troubles', 'Salmos 146:8', 'Jehová abre los ojos a los ciegos; Jehová levanta a los caídos; Jehová ama a los justos.'),
('Help in Troubles', 'Nahum 1:7', 'Jehová es bueno, fortaleza en el día de la angustia; y conoce a los que en él confían.'),
('Help in Troubles', 'Salmos 37:24', 'Aunque caiga, no quedará postrado, porque Jehová sostiene su mano.'),
('Help in Troubles', 'Salmos 32:7', 'Tú eres mi refugio; me guardarás de la angustia; con cánticos de liberación me rodearás.'),
('Help in Troubles', 'Juan 16:33', 'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo.'),
('Help in Troubles', 'Miqueas 7:8-9', 'Tú, enemiga mía, no te alegres de mí, porque aunque caí, me levantaré; aunque more en tinieblas, Jehová será mi luz. La ira de Jehová soportaré, porque pequé contra él, hasta que juzgue mi causa y haga mi juicio; él me sacará a luz; veré su justicia.'),
('Help in Troubles', 'Salmos 18:2', 'Jehová, roca mía y castillo mío, y mi libertador; Dios mío, fortaleza mía, en él confiaré; mi escudo, y la fuerza de mi salvación, mi alto refugio.'),
('Help in Troubles', 'Lamentaciones 3:31-33', 'Porque el Señor no desecha para siempre; antes si aflige, también se compadece según la multitud de sus misericordias; porque no aflige ni entristece voluntariamente a los hijos de los hombres.'),

-- Faith
('Faith', 'Hebreos 11:6', 'Pero sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay, y que es galardonador de los que le buscan.'),
('Faith', 'Job 13:15', 'He aquí, aunque él me matare, en él esperaré; no obstante, defenderé delante de él mis caminos.'),
('Faith', 'Proverbios 3:5', 'Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia.'),
('Faith', 'Mateo 9:29', 'Entonces les tocó los ojos, diciendo: Conforme a vuestra fe os sea hecho.'),
('Faith', 'Marcos 9:23', 'Jesús le dijo: Si puedes creer, al que cree todo le es posible.'),
('Faith', 'Hebreos 11:1', 'Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve.'),
('Faith', '1 Juan 5:4', 'Porque todo lo que es nacido de Dios vence al mundo; y esta es la victoria que ha vencido al mundo, nuestra fe.'),
('Faith', 'Hebreos 11:11', 'Por la fe también la misma Sara, siendo estéril, recibió fuerza para concebir; y dio a luz aun fuera del tiempo de la edad, porque creyó que era fiel quien lo había prometido.');
